let GAMES = [];
let HOLD = null;
let SAVES = { path:'', titles:0, name:'', size:'' };
let SORT = localStorage.getItem('eden-sort') || 'name';
let FILTER = localStorage.getItem('eden-filter') || 'all';

let LAUNCH_I = 0;
let RAIL_LIST = [];

function sortGames(list) {
  return list.sort((a,b) => {
    if (SORT === 'recent') return (b.lastPlayed||0) - (a.lastPlayed||0) || (a.title||'').localeCompare(b.title||'','ru');
    if (SORT === 'play') return (b.playSeconds||0) - (a.playSeconds||0) || (a.title||'').localeCompare(b.title||'','ru');
    return (a.title||'').localeCompare(b.title||'','ru');
  });
}

// «Список»: поиск и чипы-фильтры относятся только к этой вкладке.
function visibleGames() {
  const qEl = $('q');
  const q = qEl ? (qEl.value || '').trim().toLowerCase() : '';
  let list = GAMES.slice();
  if (q) list = list.filter(g => (g.title||'').toLowerCase().includes(q) || (g.developer||'').toLowerCase().includes(q) || (g.titleId||'').toLowerCase().includes(q));
  if (FILTER === 'save') list = list.filter(g => g.hasSave);
  if (FILTER === 'mod') list = list.filter(g => (g.addons||[]).some(a => a && a.enabled !== false));
  if (FILTER === 'fresh') list = list.filter(g => !g.playSeconds && !g.lastPlayed);
  return sortGames(list);
}

// «Лаунчер»: вся библиотека, всегда.
//
// Раньше здесь стоял visibleGames(), и вкладка «Список» могла урезать
// карусель до одной игры: остальные становились недоступны для запуска из
// лаунчера, а «не прокручивается» выглядело как «их тут нет».
function railGames() {
  return sortGames(GAMES.slice());
}

function progressOf(g) {
  if (!g) return 'нет данных';
  if (g.hasSave) return 'есть сейв' + (g.saveSize ? ' · ' + g.saveSize : '');
  if (g.playSeconds) return 'играли, сейва нет';
  return 'не начато';
}

function render() {
  const list = visibleGames();
  if (!N()) {
    $('list').innerHTML = '<div class="empty">Откройте из APK Eden</div>';
    return;
  }
  if (!list.length) {
    if (GAMES.length) {
      $('list').innerHTML = '<div class="empty">ничего не найдено</div>';
      return;
    }
    const folders = parse(call('folders'), { folders: [] }).folders || [];
    const bytes = folders.reduce((n, f) => n + (f.bytes || 0), 0);
    const hint = folders.length
      ? ('Папка «' + (folders[0].name || 'игры') + '» есть' +
