function renderLauncher() {
  const rail = $('rail'), dock = $('dock');
  if (!rail || !dock) return;
  RAIL_LIST = railGames();
  if (!RAIL_LIST.length) {
    rail.innerHTML = '';
    dock.innerHTML = '<div class="empty">нет игр — откройте Список и добавьте папку</div>';
    return;
  }
  if (LAUNCH_I >= RAIL_LIST.length) LAUNCH_I = 0;
  if (LAUNCH_I < 0) LAUNCH_I = RAIL_LIST.length - 1;
  rail.innerHTML = RAIL_LIST.map((g, i) => {
    const gi = GAMES.indexOf(g);
    return `<div class="slide${i===LAUNCH_I?' on':''}" data-ri="${i}" id="cvl-${gi}">▶</div>`;
  }).join('');
  rail.querySelectorAll('.slide').forEach(el => {
    el.addEventListener('click', () => {
      const i = +el.dataset.ri;
      if (i === LAUNCH_I) play(RAIL_LIST[i]);
      else snapTo(i);
    });
  });
  paintDock();
  RAIL_LIST.forEach((g, i) => {
    const gi = GAMES.indexOf(g);
    setTimeout(() => fillCover(gi, g.path), 40 * i);
  });
  requestAnimationFrame(() => {
    const el = rail.querySelector('.slide.on');
    if (el) el.scrollIntoView({ inline: 'center', block: 'nearest', behavior: 'auto' });
  });
}

function fillCover(gi, path) {
  const el = $('cvl-' + gi);
  if (!el || !path) return;
  const fn = (N() && typeof N().cover === 'function') ? 'cover' : 'icon';
  const b64 = call(fn, path);
  if (b64) el.innerHTML = '<img alt="" src="data:image/jpeg;base64,' + b64 + '">';
}

function snapTo(i) {
  if (!RAIL_LIST.length) return;
  const n = RAIL_LIST.length;
  LAUNCH_I = ((i % n) + n) % n;
  const rail = $('rail');
  if (!rail) return;
  rail.querySelectorAll('.slide').forEach(el => el.classList.toggle('on', +el.dataset.ri === LAUNCH_I));
  const el = rail.querySelector('.slide.on');
  if (el) el.scrollIntoView({ inline: 'center', block: 'nearest', behavior: 'smooth' });
  paintDock();
}

function nearestSlide() {
  const rail = $('rail');
  if (!rail) return;
  const mid = rail.scrollLeft + rail.clientWidth / 2;
  let best = 0, dist = 1e9;
  rail.querySelectorAll('.slide').forEach(el => {
    const c = el.offsetLeft + el.offsetWidth / 2;
    const d = Math.abs(c - mid);
    if (d < dist) { dist = d; best = +el.dataset.ri; }
  });
  if (best !== LAUNCH_I) {
    LAUNCH_I = best;
    rail.querySelectorAll('.slide').forEach(el => el.classList.toggle('on', +el.dataset.ri === LAUNCH_I));
    paintDock();
  }
}

function paintDock() {
  const dock = $('dock');
  if (!dock) return;
  const g = RAIL_LIST[LAUNCH_I];
  if (!g) { dock.innerHTML = '<div class="empty">нет игр</div>'; return; }
  const addons = (g.addons || []).filter(a => a && a.enabled !== false);
  const mods = addons.length
    ? addons.map(a => esc((a.kind === 'cheat' ? 'чит' : 'мод') + ' · ' + (a.name || ''))).join('<br>')
    : 'нет включённых';
  dock.innerHTML = `
    <div class="dock-head">
      <h2>${esc(g.title || 'без имени')}</h2>
      <div class="who">${esc(g.developer || '')}${g.titleId ? ' · ' + esc(g.titleId) : ''}${g.fileSize ? ' · ' + esc(g.fileSize) : ''}${g.version ? ' · ' + esc(g.version) : ''}</div>
      <div class="pos">${LAUNCH_I + 1} / ${RAIL_LIST.length}</div>
      <button class="go" id="dock-go">Запустить</button>
    </div>
    <div class="dock-body">
      <div class="facts">
        <div class="fact"><b>время</b><span>${esc(g.play || 'ещё не играли')}</span></div>
        <div class="fact"><b>запуск</b><span>${esc(g.lastPlayedLabel || 'никогда')}</span></div>
        <div class="fact"><b>прохождение</b><span>${esc(progressOf(g))}</span></div>
        <div class="fact"><b>сейв</b><span>${g.hasSave ? esc(g.saveSize || 'есть') : 'нет (слоты NEW GAME)'}</span></div>
        <div class="fact"><b>фото</b><span>${g.shots || 0}</span></div>
        <div class="fact"><b>шейдеры</b><span>${esc(g.shaderSize || 'пусто')}</span></div>
      </div>
      <div class="fact" style="width:100%"><b>моды / читы</b><span>${mods}</span></div>
      <div class="dock-shots" id="dock-shots"></div>
      <div class="row" style="margin-top:8px">
        <button class="ghost" id="dock-core">Ядро: Eden</button>
        <button class="ghost" id="dock-cpu">CPU: —</button>
        <button class="ghost" id="dock-shots-btn">Все фото</button>
        <button class="ghost" id="dock-props">Свойства</button>
        <button class="ghost" id="dock-aaa">AAA минимум</button>
      </div>
    </div>`;
  $('dock-go').onclick = () => play(g);
  $('dock-shots-btn').onclick = () => openShots(g);
  $('dock-props').onclick = () => { if (N() && N().openGameMenu) N().openGameMenu(g.path); };
  $('dock-aaa').onclick = () => {
    const r = parse(call('applyAaaMode'), { message: 'нет моста' });
    const f = dock.querySelector('.who');
    if (f) f.textContent = r.message || '';
  };
  paintCores();
  if ($('dock-core')) $('dock-core').onclick = ev => { ev.stopPropagation(); openEnginesSheet(); };
  if ($('dock-cpu')) $('dock-cpu').onclick = ev => { ev.stopPropagation(); cycleCpu(); };
  fillDockShots(g);
}

function paintCores() {
  const eng = parse(call('engines'), { currentLabel: 'Eden', launchLabel: 'Eden' });
  const set = parse(call('settings'), { cpuLabel: '' });
  const core = $('dock-core');
  if (core) {
    const same = (eng.current || 'eden') === (eng.launch || 'eden');
    core.textContent = same
      ? ('Ядро: ' + (eng.currentLabel || 'Eden'))
      : ('Ядро: ' + (eng.currentLabel || '?') + ' · игры: ' + (eng.launchLabel || 'Eden'));
  }
  const cpu = $('dock-cpu');
  if (cpu) cpu.textContent = 'CPU: ' + (set.cpuLabel || '—');
}

