480	let SAVES = { path:'', titles:0, name:'', size:'' };
481	let SORT = localStorage.getItem('eden-sort') || 'name';
482	let FILTER = localStorage.getItem('eden-filter') || 'all';
483	
484	let LAUNCH_I = 0;
485	let RAIL_LIST = [];
486	
487	function sortGames(list) {
488	  return list.sort((a,b) => {
489	    if (SORT === 'recent') return (b.lastPlayed||0) - (a.lastPlayed||0) || (a.title||'').localeCompare(b.title||'','ru');
490	    if (SORT === 'play') return (b.playSeconds||0) - (a.playSeconds||0) || (a.title||'').localeCompare(b.title||'','ru');
491	    return (a.title||'').localeCompare(b.title||'','ru');
492	  });
493	}
494	
495	// «Список»: поиск и чипы-фильтры относятся только к этой вкладке.
496	function visibleGames() {
497	  const qEl = $('q');
498	  const q = qEl ? (qEl.value || '').trim().toLowerCase() : '';
499	  let list = GAMES.slice();
500	  if (q) list = list.filter(g => (g.title||'').toLowerCase().includes(q) || (g.developer||'').toLowerCase().includes(q) || (g.titleId||'').toLowerCase().includes(q));
501	  if (FILTER === 'save') list = list.filter(g => g.hasSave);
502	  if (FILTER === 'mod') list = list.filter(g => (g.addons||[]).some(a => a && a.enabled !== false));
503	  if (FILTER === 'fresh') list = list.filter(g => !g.playSeconds && !g.lastPlayed);
504	  return sortGames(list);
505	}
506	
507	// «Лаунчер»: вся библиотека, всегда.
508	//
509	// Раньше здесь стоял visibleGames(), и вкладка «Список» могла урезать
510	// карусель до одной игры: остальные становились недоступны для запуска из
511	// лаунчера, а «не прокручивается» выглядело как «их тут нет».
512	function railGames() {
513	  return sortGames(GAMES.slice());
514	}
515	
516	function progressOf(g) {
517	  if (!g) return 'нет данных';
518	  if (g.hasSave) return 'есть сейв' + (g.saveSize ? ' · ' + g.saveSize : '');
519	  if (g.playSeconds) return 'играли, сейва нет';
520	  return 'не начато';
521	}
522	
523	function render() {
524	  const list = visibleGames();
525	  if (!N()) {
526	    $('list').innerHTML = '<div class="empty">Откройте из APK Eden</div>';
527	    return;
528	  }
529	  if (!list.length) {
530	    if (GAMES.length) {
531	      $('list').innerHTML = '<div class="empty">ничего не найдено</div>';
532	      return;
533	    }
534	    const folders = parse(call('folders'), { folders: [] }).folders || [];
535	    const bytes = folders.reduce((n, f) => n + (f.bytes || 0), 0);
536	    const hint = folders.length
537	      ? ('Папка «' + (folders[0].name || 'игры') + '» есть' +
538	         (folders[0].size ? ' · ' + folders[0].size : '') +
539	         ', но игр нет. Если ключи ✕ — сначала ключи, не сканер.')
540	      : 'Нет игр в кэше. Добавьте папку снизу.';
541	    $('list').innerHTML = '<div class="empty">' + hint +
542	      '<div style="margin-top:14px"><button class="ghost" id="btn-find">Найти игры</button></div></div>';
543	    const b = $('btn-find');
544	    if (b) b.onclick = findGames;
545	    return;
546	  }
547	  $('list').innerHTML = list.map(g => {
548	    const i = GAMES.indexOf(g);
549	    const save = g.hasSave ? (' · сейв ' + (g.saveSize || 'есть')) : '';
550	    const addons = (g.addons || []).filter(a => a && a.enabled !== false);
551	    const side = addons.length ? `<div class="addons">${addons.map(a => {
552	      const files = (a.files || []).map(f =>
553	        `<button class="addon-file" data-path="${esc(f.path)}" data-name="${esc(f.name)}">${esc(f.name)}</button>`
554	      ).join('');
555	      return `<div class="addon-name">${esc(a.kind === 'cheat' ? 'чит' : 'мод')} · ${esc(a.name)}</div>${files}`;
556	    }).join('')}</div>` : '';
557	    const bits = [];
558	    if (g.play) bits.push(g.play);
559	    if (g.lastPlayedLabel) bits.push(g.lastPlayedLabel);
560	    if (g.shots) bits.push('фото ' + g.shots);
561	    if (g.shaderSize) bits.push('шейдеры ' + g.shaderSize);
562	    const stats = bits.length ? `<div class="stats">${bits.map(b => `<span class="play">${esc(b)}</span>`).join('')}</div>` : '';
563	    const shot = g.lastShot ? `<div class="shot" id="sh-${i}" data-shot="1"></div>` : '';
564	    const tid = g.titleId ? `<div class="tid" data-tid="${esc(g.titleId)}">${esc(g.titleId)}${g.fileSize ? ' · ' + esc(g.fileSize) : ''}${g.version ? ' · ' + esc(g.version) : ''}</div>` : '';
565	    return `<div class="game" data-i="${i}">
566	      <div class="thumb" id="ic-${i}">▶</div>
567	      <div class="meta">
568	        <div class="title">${esc(g.title || 'без имени')}</div>
569	        <div class="sub">${esc(g.developer || '')}${save}</div>
570	        ${stats}
571	        ${tid}
572	      </div>
573	      ${shot}
574	      ${side}
575	    </div>`;
576	  }).join('');
577	  $('list').querySelectorAll('.game').forEach(el => {
578	    const g = GAMES[+el.dataset.i];
579	    el.addEventListener('click', ev => {
580	      if (ev.target.closest('.addon-file')) return;
581	      if (ev.target.closest('[data-shot]')) { ev.stopPropagation(); openShots(g); return; }
582	      const tidEl = ev.target.closest('[data-tid]');
583	      if (tidEl && tidEl.dataset.tid) {
584	        ev.stopPropagation();
585	        copyTid(tidEl.dataset.tid);
586	        return;
587	      }
588	      play(g);
589	    });
590	    el.addEventListener('contextmenu', ev => { ev.preventDefault(); holdMenu(g); });
591	    let t = 0;
